package com.fasttravel.controller;import com.fasttravel.dto.ApiResponse;import com.fasttravel.service.TripService;import lombok.RequiredArgsConstructor;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;@RestController @RequestMapping("/api/public") @RequiredArgsConstructor public class PublicController{private final TripService trips;@GetMapping("/stations") public ApiResponse<?> stations(){return ApiResponse.ok(trips.stations());}@GetMapping("/trips") public ApiResponse<?> search(@RequestParam(required=false)Long origin,@RequestParam(required=false)Long destination,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate date){return ApiResponse.ok(trips.search(origin,destination,date));}@GetMapping("/trips/{id}") public ApiResponse<?> detail(@PathVariable Long id){return ApiResponse.ok(trips.detail(id));}@GetMapping("/trips/{id}/seats") public ApiResponse<?> seats(@PathVariable Long id){return ApiResponse.ok(trips.seats(id));}}
